window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-ca06f3679d6f03a0"]={"versions": [{"id": "FIG-ca06f3679d6f03a0", "releases": ["R3.2.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Strukturelles Datenlayout-Diagramm zur Darstellung der E2E-PDU-Serialisierung und der CRC-Berechnung im Rahmen des E2E-Profils 1 (Schritt 4: CRC-Abschlussberechnung) der AUTOSAR E2E Library. Das Diagramm zeigt die Bytestruktur einer zu übertragenden Botschaft bzw. eines Datenpuffers (z. B. auf COM-/PDU-Ebene) inklusive der Einbeziehung der Data ID in die Prüfsummenberechnung.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Data Id</strong>: Konfigurationsparameter (eindeutiger Bezeichner des Datenstroms), der nicht als Nutzdaten im Frame übertragen wird, jedoch als statischer Eingabewert in die CRC-Berechnung einfließt.\n</li><li><strong>PDU-Byte-Array</strong> (7 dargestellte Byte-Positionen mit orange hinterlegten Feldern/Zellen):\n<ul class=\"fig-list\"><li>Byte 0: <code>CRC</code> – Zielfeld für die 8-Bit-Prüfsumme (CRC-8).\n</li><li>Byte 1: Aufgeteiltes Byte bestehend aus einem fixen Nibble (<code>0xF</code>) und dem 4-Bit-<code>Counter</code> (Alive Counter).\n</li><li>Byte 2: Erstes Byte des Nutzsignals <code>Sig 1</code>.\n</li><li>Byte 3: Unbeschriftetes Datenbyte (Nutzdaten/Signalbereich).\n</li><li>Byte 4: Fixes Füll- bzw. Maskierungsbyte (<code>0xFF</code>).\n</li><li>Byte 5 &amp; 6: Zusammenhängendes 2-Byte-Feld für das Nutzsignal <code>Sig 1</code> (erneut bzw. Fortsetzung).\n</li></ul>\n</li><li><strong>Berechnungs- und Datenfluss</strong>:\n<ul class=\"fig-list\"><li>Eine geschweifte Klammer fasst die Datenbytes ab Byte 1 bis Byte 6 zusammen.\n</li><li>Ein gemeinsamer Datenflusszweig verbindet die geschweifte Klammer (PDU-Nutzdaten/Counter) und das Element <code>Data Id</code> über eine Pfeillinie direkt mit dem Zielfeld <code>CRC</code> in Byte 0.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Das PDU-Array enthält die vorbereiteten Datenbytes inklusive Zählerwert (<code>Counter</code>), statischer Maskierungen (<code>0xF</code>, <code>0xFF</code>) und Nutzsignaldaten (<code>Sig 1</code>).\n</li><li>Für die finale Berechnung des CRC-Werts wird der Datenbereich von Byte 1 bis Byte 6 zusammen mit der <code>Data Id</code> als Eingabe für den E2E-CRC-Algorithmus herangezogen.\n</li><li>Der resultierende Prüfsummenwert wird in das dafür vorgesehene erste Byte (<code>CRC</code>) der PDU geschrieben (Schritt 4 des Schutzmechanismus), womit die PDU vollständig für die Übertragung geschützt ist.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li>Zeigt die normative Berechnungsvorschrift für E2E Profile 1 (Data-ID-Modus und CRC-Berechnung über die gesamte PDU abzüglich des CRC-Felds selbst).\n</li><li>Die <code>Data Id</code> dient dem Schutz vor Fehladressierung und wird softwareseitig über die CRC-Polynomberechnung eingebunden, ohne Busbandbreite zu belegen.\n</li><li>Softwareentwickler und Integratoren müssen sicherstellen, dass die Bytereihenfolge, die Bitmaskierung des Counters (Nibble-Zuordnung) und die Positionierung des CRC-Bytes exakt mit der Signal- bzw. PDU-Matrix übereinstimmen.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-7925c1a8417c64ba", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Strukturelles Datenlayout-Diagramm zur Darstellung der E2E-PDU-Serialisierung und der CRC-Berechnung im Rahmen des E2E-Profils 1 (Schritt 4: CRC-Abschlussberechnung) der AUTOSAR E2E Library. Das Diagramm zeigt die Bytestruktur einer zu übertragenden Botschaft bzw. eines Datenpuffers (z. B. auf COM-/PDU-Ebene) inklusive der Einbeziehung der Data ID in die Prüfsummenberechnung.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Data Id</strong>: Konfigurationsparameter (eindeutiger Bezeichner des Datenstroms), der nicht als Nutzdaten im Frame übertragen wird, jedoch als statischer Eingabewert in die CRC-Berechnung einfließt.\n</li><li><strong>PDU-Byte-Array</strong> (7 dargestellte Byte-Positionen mit orange hinterlegten Feldern/Zellen):\n<ul class=\"fig-list\"><li>Byte 0: <code>CRC</code> – Zielfeld für die 8-Bit-Prüfsumme (CRC-8).\n</li><li>Byte 1: Aufgeteiltes Byte bestehend aus einem fixen Nibble (<code>0xF</code>) und dem 4-Bit-<code>Counter</code> (Alive Counter).\n</li><li>Byte 2: Erstes Byte des Nutzsignals <code>Sig 1</code>.\n</li><li>Byte 3: Unbeschriftetes Datenbyte (Nutzdaten/Signalbereich).\n</li><li>Byte 4: Fixes Füll- bzw. Maskierungsbyte (<code>0xFF</code>).\n</li><li>Byte 5 &amp; 6: Zusammenhängendes 2-Byte-Feld für das Nutzsignal <code>Sig 1</code> (erneut bzw. Fortsetzung).\n</li></ul>\n</li><li><strong>Berechnungs- und Datenfluss</strong>:\n<ul class=\"fig-list\"><li>Eine geschweifte Klammer fasst die Datenbytes ab Byte 1 bis Byte 6 zusammen.\n</li><li>Ein gemeinsamer Datenflusszweig verbindet die geschweifte Klammer (PDU-Nutzdaten/Counter) und das Element <code>Data Id</code> über eine Pfeillinie direkt mit dem Zielfeld <code>CRC</code> in Byte 0.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Das PDU-Array enthält die vorbereiteten Datenbytes inklusive Zählerwert (<code>Counter</code>), statischer Maskierungen (<code>0xF</code>, <code>0xFF</code>) und Nutzsignaldaten (<code>Sig 1</code>).\n</li><li>Für die finale Berechnung des CRC-Werts wird der Datenbereich von Byte 1 bis Byte 6 zusammen mit der <code>Data Id</code> als Eingabe für den E2E-CRC-Algorithmus herangezogen.\n</li><li>Der resultierende Prüfsummenwert wird in das dafür vorgesehene erste Byte (<code>CRC</code>) der PDU geschrieben (Schritt 4 des Schutzmechanismus), womit die PDU vollständig für die Übertragung geschützt ist.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li>Zeigt die normative Berechnungsvorschrift für E2E Profile 1 (Data-ID-Modus und CRC-Berechnung über die gesamte PDU abzüglich des CRC-Felds selbst).\n</li><li>Die <code>Data Id</code> dient dem Schutz vor Fehladressierung und wird softwareseitig über die CRC-Polynomberechnung eingebunden, ohne Busbandbreite zu belegen.\n</li><li>Softwareentwickler und Integratoren müssen sicherstellen, dass die Bytereihenfolge, die Bitmaskierung des Counters (Nibble-Zuordnung) und die Positionierung des CRC-Bytes exakt mit der Signal- bzw. PDU-Matrix übereinstimmen.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-ca06f3679d6f03a0", "to": "FIG-7925c1a8417c64ba", "fr": "R3.2.3", "tr": "R4.1.3", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
